// Tests for CanvasRoute — renders the neutral empty state (with a New
// action) when no ?workflowId= query param is present, and mounts
// CanvasEditor (threading onWorkflowChange -> ?workflowId=) when one is.

import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { http, HttpResponse } from "msw";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { expect, test, vi, afterEach } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { server } from "../setup";

vi.mock("../../src/canvas/CanvasEditor", () => ({
  CanvasEditor: ({
    workflowId,
    onWorkflowChange,
  }: {
    workflowId: string;
    onWorkflowChange?: (id: string) => void;
  }) => (
    <div data-testid="canvas-editor-stub">
      {workflowId}
      <button
        type="button"
        data-testid="simulate-open"
        onClick={() => onWorkflowChange?.("wf-from-editor")}
      />
    </div>
  ),
}));

import CanvasRoute from "../../src/routes/CanvasRoute";

afterEach(() => {
  server.resetHandlers();
});

test("renders the empty state when no workflowId query param is present", () => {
  render(
    <MemoryRouter initialEntries={["/canvas"]}>
      <Routes>
        <Route path="/canvas" element={<CanvasRoute />} />
      </Routes>
    </MemoryRouter>,
  );
  expect(
    screen.getByRole("heading", { name: m.workflow_canvas_empty_title() }),
  ).toBeInTheDocument();
  expect(screen.queryByTestId("canvas-editor-stub")).not.toBeInTheDocument();
});

test("renders CanvasEditor with the workflowId from the query string", () => {
  render(
    <MemoryRouter initialEntries={["/canvas?workflowId=wf-42"]}>
      <Routes>
        <Route path="/canvas" element={<CanvasRoute />} />
      </Routes>
    </MemoryRouter>,
  );
  expect(screen.getByTestId("canvas-editor-stub")).toHaveTextContent("wf-42");
});

test("the empty state's New button creates a workflow and switches to the editor", async () => {
  server.use(
    http.post("/api/v1/workflows", () =>
      HttpResponse.json({
        data: {
          id: "wf-new",
          name: "Untitled workflow",
          description: "",
          status: "",
          canvas_id: "",
          project_id: "",
          created_at: "",
        },
      }),
    ),
  );

  const user = userEvent.setup();
  render(
    <MemoryRouter initialEntries={["/canvas"]}>
      <Routes>
        <Route path="/canvas" element={<CanvasRoute />} />
      </Routes>
    </MemoryRouter>,
  );

  await user.click(screen.getByRole("button", { name: m.workflow_toolbar_new() }));

  await waitFor(() =>
    expect(screen.getByTestId("canvas-editor-stub")).toHaveTextContent("wf-new"),
  );
});

test("the empty state's New button surfaces no crash when createWorkflow fails", async () => {
  server.use(
    http.post("/api/v1/workflows", () =>
      HttpResponse.json({ error: { message: "boom" } }, { status: 500 }),
    ),
  );

  const user = userEvent.setup();
  render(
    <MemoryRouter initialEntries={["/canvas"]}>
      <Routes>
        <Route path="/canvas" element={<CanvasRoute />} />
      </Routes>
    </MemoryRouter>,
  );

  await user.click(screen.getByRole("button", { name: m.workflow_toolbar_new() }));

  await waitFor(() =>
    expect(
      screen.getByRole("heading", { name: m.workflow_canvas_empty_title() }),
    ).toBeInTheDocument(),
  );
  expect(screen.queryByTestId("canvas-editor-stub")).not.toBeInTheDocument();
});

test("CanvasEditor's onWorkflowChange updates the ?workflowId= query param", async () => {
  const user = userEvent.setup();
  render(
    <MemoryRouter initialEntries={["/canvas?workflowId=wf-42"]}>
      <Routes>
        <Route path="/canvas" element={<CanvasRoute />} />
      </Routes>
    </MemoryRouter>,
  );

  await user.click(screen.getByTestId("simulate-open"));

  await waitFor(() =>
    expect(screen.getByTestId("canvas-editor-stub")).toHaveTextContent("wf-from-editor"),
  );
});

// ---------------------------------------------------------------------------
// Browser tab title (#1357 AC 2)
// ---------------------------------------------------------------------------

test("the open workflow's name becomes the tab title, and is restored on unmount", async () => {
  server.use(
    http.get("/api/v1/workflows/wf-42", () =>
      HttpResponse.json({ data: { id: "wf-42", name: "Nightly digest" } }),
    ),
  );

  document.title = "OmniCore";

  const { unmount } = render(
    <MemoryRouter initialEntries={["/canvas?workflowId=wf-42"]}>
      <Routes>
        <Route path="/canvas" element={<CanvasRoute />} />
      </Routes>
    </MemoryRouter>,
  );

  await waitFor(() => expect(document.title).toBe("Nightly digest"));

  unmount();
  // The shell owns the document title, so leaving a stale workflow name in the
  // tab after navigating to another vertical is the failure this guards.
  expect(document.title).toBe("OmniCore");
});

test("no workflow open leaves the tab title alone", async () => {
  document.title = "OmniCore";

  render(
    <MemoryRouter initialEntries={["/canvas"]}>
      <Routes>
        <Route path="/canvas" element={<CanvasRoute />} />
      </Routes>
    </MemoryRouter>,
  );

  await screen.findByRole("heading", { name: m.workflow_canvas_empty_title() });
  expect(document.title).toBe("OmniCore");
});


