/**
 * tests for ProjectDetailRoute (#1353) and its tag filter (#1356 step 3).
 */
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { http, HttpResponse } from "msw";
import { expect, test, vi } from "vitest";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import { server } from "../setup";
import ProjectDetailRoute from "../../src/routes/ProjectDetailRoute";

vi.mock("@omnicore-platform/platform-chrome", async () => {
  const actual = await vi.importActual<
    typeof import("@omnicore-platform/platform-chrome")
  >("@omnicore-platform/platform-chrome");
  return { ...actual, useLocale: () => "en-US" };
});

function projectPayload(overrides: Record<string, unknown> = {}) {
  return {
    id: "p1",
    name: "Marketing",
    description: "Campaign automations",
    workflow_count: 2,
    caller_role: "OWNER",
    created_at: "",
    updated_at: "",
    ...overrides,
  };
}

function renderAt(search = "") {
  return render(
    <MemoryRouter initialEntries={[`/workflows/projects/p1${search}`]}>
      <Routes>
        <Route path="/workflows/projects/:projectId" element={<ProjectDetailRoute />} />
      </Routes>
    </MemoryRouter>,
  );
}

test("renders the project header and its workflows", async () => {
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", () =>
      HttpResponse.json({
        data: {
          workflows: [
            { id: "w1", name: "Nightly digest", status: "WORKFLOW_STATUS_ACTIVE", tags: [] },
          ],
        },
      }),
    ),
  );

  renderAt();

  expect(
    await screen.findByRole("heading", { name: "Marketing" }),
  ).toBeInTheDocument();
  expect(screen.getByText("Campaign automations")).toBeInTheDocument();
  expect(
    screen.getByRole("link", { name: "Nightly digest" }),
  ).toBeInTheDocument();
});

test("a caller with write access sees the Settings link", async () => {
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload({ caller_role: "EDITOR" }) }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", () =>
      HttpResponse.json({ data: { workflows: [] } }),
    ),
  );

  renderAt();
  expect(
    await screen.findByRole("link", { name: m.workflow_project_detail_settings() }),
  ).toBeInTheDocument();
});

test("a read-only caller gets neither Settings nor a delete button", async () => {
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload({ caller_role: "VIEWER" }) }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", () =>
      HttpResponse.json({
        data: { workflows: [{ id: "w1", name: "Nightly digest", tags: [] }] },
      }),
    ),
  );

  renderAt();
  await screen.findByRole("link", { name: "Nightly digest" });

  // Offering a control the server will refuse is worse than not offering it.
  expect(
    screen.queryByRole("link", { name: m.workflow_project_detail_settings() }),
  ).not.toBeInTheDocument();
  expect(
    screen.queryByRole("button", {
      name: m.workflow_project_row_delete({ name: "Nightly digest" }),
    }),
  ).not.toBeInTheDocument();
});

test("an empty project prompts you to add a workflow", async () => {
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload({ workflow_count: 0 }) }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", () =>
      HttpResponse.json({ data: { workflows: [] } }),
    ),
  );

  renderAt();
  expect(
    await screen.findByText(m.workflow_project_detail_empty()),
  ).toBeInTheDocument();
});

test("an over-filtered list says so instead of claiming the project is empty", async () => {
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", () =>
      HttpResponse.json({ data: { workflows: [] } }),
    ),
    http.get("/api/v1/workflows/tags", () =>
      HttpResponse.json({ data: { tags: ["release"] } }),
    ),
  );

  renderAt("?tag=release");

  // Two distinct empty states: conflating them would tell someone their
  // project is empty when it is not.
  expect(
    await screen.findByText(
      m.workflow_project_detail_empty_for_tag({ tag: "release" }),
    ),
  ).toBeInTheDocument();
});

test("the tag filter goes to the server and lands in the URL", async () => {
  const user = userEvent.setup();
  const seen: string[] = [];
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", ({ request }) => {
      seen.push(new URL(request.url).searchParams.get("tag") ?? "");
      return HttpResponse.json({ data: { workflows: [] } });
    }),
    http.get("/api/v1/workflows/tags", () =>
      HttpResponse.json({ data: { tags: ["release"] } }),
    ),
  );

  renderAt();
  const chip = await screen.findByRole("radio", { name: "release" });
  await user.click(chip);

  // Server-side, because the list is paged — a client-side filter would
  // silently hide matches beyond the current page.
  await waitFor(() => expect(seen).toContain("release"));
});

test("a missing project renders an alert, not a blank page", async () => {
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ error: { message: "project not found" } }, { status: 404 }),
    ),
  );

  renderAt();
  expect(await screen.findByRole("alert")).toHaveTextContent("project not found");
});

test("deleting a workflow confirms first, then refetches the list", async () => {
  const user = userEvent.setup();
  let listCalls = 0;
  let deleted = "";
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", () => {
      listCalls += 1;
      return HttpResponse.json({
        data: {
          workflows:
            listCalls === 1 ? [{ id: "w1", name: "Nightly digest", tags: [] }] : [],
        },
      });
    }),
    http.delete("/api/v1/workflows/w1", ({ request }) => {
      deleted = new URL(request.url).pathname;
      return new HttpResponse(null, { status: 204 });
    }),
  );

  renderAt();
  await screen.findByRole("link", { name: "Nightly digest" });

  await user.click(
    screen.getByRole("button", {
      name: m.workflow_project_row_delete({ name: "Nightly digest" }),
    }),
  );
  // A confirm stands between the button and the delete.
  const dialog = await screen.findByRole("alertdialog");
  expect(dialog).toBeInTheDocument();

  await user.click(
    screen.getByRole("button", { name: m.workflow_delete_confirm_confirm() }),
  );

  await waitFor(() => expect(deleted).toBe("/api/v1/workflows/w1"));
  await waitFor(() => expect(listCalls).toBeGreaterThan(1));
});

test("cancelling the confirm deletes nothing", async () => {
  const user = userEvent.setup();
  let deleteCalls = 0;
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", () =>
      HttpResponse.json({
        data: { workflows: [{ id: "w1", name: "Nightly digest", tags: [] }] },
      }),
    ),
    http.delete("/api/v1/workflows/w1", () => {
      deleteCalls += 1;
      return new HttpResponse(null, { status: 204 });
    }),
  );

  renderAt();
  await screen.findByRole("link", { name: "Nightly digest" });
  await user.click(
    screen.getByRole("button", {
      name: m.workflow_project_row_delete({ name: "Nightly digest" }),
    }),
  );
  await screen.findByRole("alertdialog");
  await user.click(
    screen.getByRole("button", { name: m.workflow_delete_confirm_cancel() }),
  );

  expect(deleteCalls).toBe(0);
});

test("a failed workflow list is an alert, distinct from the empty state", async () => {
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", () =>
      HttpResponse.json({ error: { message: "list failed" } }, { status: 500 }),
    ),
  );

  renderAt();
  expect(await screen.findByRole("alert")).toHaveTextContent("list failed");
  expect(
    screen.queryByText(m.workflow_project_detail_empty()),
  ).not.toBeInTheDocument();
});

test("a workflow row links to the canvas with the key CanvasRoute reads", async () => {
  // Regression: this href was built with `?workflow=`, which CanvasRoute
  // ignores — it reads `workflowId`. An unknown key does not error, it opens
  // a blank canvas, so nothing failed loudly. The row's own test only ever
  // asserted that the `href` prop was passed through, so the key itself was
  // unguarded until here.
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", () =>
      HttpResponse.json({
        data: {
          workflows: [
            { id: "w 1/2", name: "Nightly digest", status: "WORKFLOW_STATUS_ACTIVE", tags: [] },
          ],
        },
      }),
    ),
  );

  renderAt();

  expect(await screen.findByRole("link", { name: "Nightly digest" })).toHaveAttribute(
    "href",
    "/workflows/canvas?workflowId=w%201%2F2",
  );
});

// jsx-no-literals forbids a bare string in JSX, test files included.
const LIST_MARKER = "Projects list";

test("the back control is a button that returns to the projects list", async () => {
  const user = userEvent.setup();
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
    http.get("/api/v1/workflows/projects/p1/workflows", () =>
      HttpResponse.json({ data: { workflows: [] } }),
    ),
  );

  render(
    <MemoryRouter initialEntries={["/workflows/projects/p1"]}>
      <Routes>
        <Route path="/workflows/projects/:projectId" element={<ProjectDetailRoute />} />
        <Route path="/workflows/projects" element={<h1>{LIST_MARKER}</h1>} />
      </Routes>
    </MemoryRouter>,
  );

  // A button by request, not a link — so role matters, and the accessible
  // name stays the unabbreviated phrase while the visible label is short.
  const back = await screen.findByRole("button", {
    name: m.workflow_project_detail_back(),
  });
  expect(back).toHaveTextContent(m.workflow_project_detail_back_label());

  await user.click(back);
  expect(
    await screen.findByRole("heading", { name: LIST_MARKER }),
  ).toBeInTheDocument();
});


