/**
 * tests for ProjectSettingsRoute (#1354), which also hosts the inline
 * sharing section (#1355).
 */
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { http, HttpResponse } from "msw";
import { beforeEach, expect, test } from "vitest";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import { server } from "../setup";
import ProjectSettingsRoute from "../../src/routes/ProjectSettingsRoute";

function projectPayload(overrides: Record<string, unknown> = {}) {
  return {
    id: "p1",
    name: "Marketing",
    description: "Campaign automations",
    workflow_count: 3,
    caller_role: "OWNER",
    ...overrides,
  };
}

// The sharing panel is part of this page now, so it reads the roster on every
// render. Left unstubbed those two GETs fail and the panel raises its own
// role="alert", which makes a bare getByRole("alert") ambiguous in the tests
// that assert a save error. Individual tests still override these.
beforeEach(() => {
  server.use(
    http.get("/api/v1/workflows/projects/p1/members", () =>
      HttpResponse.json({ data: { members: [] } }),
    ),
    http.get("/api/v1/workflows/org/members", () =>
      HttpResponse.json({ data: { members: [] } }),
    ),
  );
});

/** Renders the settings route plus a probe for where a redirect landed. */
function renderRoute() {
  return render(
    <MemoryRouter initialEntries={["/workflows/projects/p1/settings"]}>
      <Routes>
        <Route
          path="/workflows/projects/:projectId/settings"
          element={<ProjectSettingsRoute />}
        />
        <Route
          path="/workflows/projects"
          element={<div data-testid="projects-list" />}
        />
      </Routes>
    </MemoryRouter>,
  );
}

test("seeds the form from the project", async () => {
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
  );
  renderRoute();

  const name = await screen.findByLabelText(
    m.workflow_project_settings_name_label(),
  );
  // findByLabelText resolves as soon as the input EXISTS, which is one tick
  // before the effect that seeds it from the fetched project — so this has to
  // wait for the value, not just the element. Same race the edit tests below
  // guard against.
  await waitFor(() => expect(name).toHaveValue("Marketing"));
  expect(
    screen.getByLabelText(m.workflow_project_settings_description_label()),
  ).toHaveValue("Campaign automations");
});

test("saving PATCHes name and description and confirms", async () => {
  const user = userEvent.setup();
  let body: unknown = null;
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
    http.patch("/api/v1/workflows/projects/p1", async ({ request }) => {
      body = await request.json();
      return HttpResponse.json({ data: projectPayload({ name: "Renamed" }) });
    }),
  );
  renderRoute();

  const name = await screen.findByLabelText(
    m.workflow_project_settings_name_label(),
  );
  // Wait for the effect to seed the form before editing. findByLabelText
  // resolves as soon as the input exists, which is BEFORE the fetched project
  // has been applied — clearing then is a race the seed wins, leaving the
  // typed text appended to the re-seeded name.
  await waitFor(() => expect(name).toHaveValue("Marketing"));
  await user.clear(name);
  await user.type(name, "Renamed");
  await user.click(
    screen.getByRole("button", { name: m.workflow_project_settings_save() }),
  );

  await waitFor(() =>
    expect(body).toEqual({
      name: "Renamed",
      description: "Campaign automations",
    }),
  );
  // role="status", not "alert": a successful save should not talk over a
  // screen-reader user mid-sentence.
  await waitFor(() =>
    expect(screen.getByRole("status")).toHaveTextContent(
      m.workflow_project_settings_saved(),
    ),
  );
});

test("an empty name blocks Save and explains why", async () => {
  const user = userEvent.setup();
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
  );
  renderRoute();

  const name = await screen.findByLabelText(
    m.workflow_project_settings_name_label(),
  );
  // Wait for the effect to seed the form before editing. findByLabelText
  // resolves as soon as the input exists, which is BEFORE the fetched project
  // has been applied — clearing then is a race the seed wins, leaving the
  // typed text appended to the re-seeded name.
  await waitFor(() => expect(name).toHaveValue("Marketing"));
  await user.clear(name);

  expect(
    screen.getByRole("button", { name: m.workflow_project_settings_save() }),
  ).toBeDisabled();
  expect(screen.getByRole("alert")).toHaveTextContent(
    m.workflow_project_settings_name_required(),
  );
  expect(name).toHaveAttribute("aria-invalid", "true");
});

test("a failed save is announced and the form keeps the draft", async () => {
  const user = userEvent.setup();
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload() }),
    ),
    http.patch("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ error: { message: "denied" } }, { status: 403 }),
    ),
  );
  renderRoute();

  const name = await screen.findByLabelText(
    m.workflow_project_settings_name_label(),
  );
  // Wait for the effect to seed the form before editing. findByLabelText
  // resolves as soon as the input exists, which is BEFORE the fetched project
  // has been applied — clearing then is a race the seed wins, leaving the
  // typed text appended to the re-seeded name.
  await waitFor(() => expect(name).toHaveValue("Marketing"));
  await user.clear(name);
  await user.type(name, "Attempted");
  await user.click(
    screen.getByRole("button", { name: m.workflow_project_settings_save() }),
  );

  await waitFor(() =>
    expect(screen.getByRole("alert")).toHaveTextContent("denied"),
  );
  expect(name).toHaveValue("Attempted");
});

test("a read-only caller gets an explanation, not a form that will 403", async () => {
  server.use(
    http.get("/api/v1/workflows/projects/p1", () =>
      HttpResponse.json({ data: projectPayload({ caller_role: "VIEWER" }) }),
    ),
  );
  renderRoute();

  expect(
    await screen.findByText(m.workflow_project_settings_read_only()),
  ).toBeInTheDocument();
  expect(
    screen.queryByLabelText(m.workflow_project_settings_name_label()),
