    release = resolve;
  });
  const instantiations = vi.fn();
  server.use(
    http.post("/api/v1/workflows/templates/:id\\:instantiate", async () => {
      instantiations();
      await gate;
      return HttpResponse.json({ data: { workflow_id: "w-new" } });
    }),
  );
  renderRoute();
  await waitForLibrary();

  const card = screen.getByText("Your First Workflow").closest("li") as HTMLElement;
