  await waitFor(() =>
    expect(
      within(card).getByRole("button", { name: m.workflow_templates_use_pending() }),
    ).toBeDisabled(),
  );

  // Drive the handler directly rather than through the disabled button, so
  // the assertion is about the guard and not about `disabled`.
  const otherCard = screen.getByText("Our Approval Gate").closest("li") as HTMLElement;
  await user.click(
    within(otherCard).getByRole("button", { name: m.workflow_templates_use() }),
  );

  expect(instantiations).toHaveBeenCalledTimes(1);
  release();
  await waitFor(() => expect(screen.getByTestId("canvas-landed")).toBeInTheDocument());
});

