// Tests for TemplatesRoute — the templates library (#1345).
//
// These drive the route through the REAL filter pipeline and the REAL card /
// section components, so the assertions are about the page a user sees:
// sections in order (#1346), chips narrowing with AND semantics (#1347),
// search composing with them (#1348), Use Template navigating to the new
// workflow (#1349), and Delete only where it is legal.
//
// Visibility is deliberately asserted by DOM PRESENCE, never by computed
// style: jsdom does not evaluate CSS, so a `toBeVisible()` here would pass on
// markup the real browser renders wrong. Collapse is implemented by removing
// the list from the DOM precisely so this test can mean something — and so a
// keyboard user cannot tab into an invisible section.

import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { http, HttpResponse } from "msw";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { afterEach, expect, test, vi } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { server } from "../setup";
import TemplatesRoute from "../../src/routes/TemplatesRoute";

afterEach(() => {
  server.resetHandlers();
});

interface WireTemplate {
  readonly id: string;
  readonly name: string;
  readonly description?: string;
  readonly category: string;
  readonly features?: readonly string[];
  readonly builtin?: boolean;
  readonly unknown_node_types?: readonly string[];
}

function mockLibrary(templates: readonly WireTemplate[]) {
  server.use(
    http.get("/api/v1/workflows/templates", () =>
      HttpResponse.json({
        data: {
          templates: templates.map((t) => ({
            description: "",
            tags: [],
            features: [],
            unknown_node_types: [],
            builtin: false,
            created_at: "",
            ...t,
          })),
        },
      }),
    ),
  );
}

const LIBRARY: readonly WireTemplate[] = [
  {
    id: "builtin-first-workflow",
    name: "Your First Workflow",
    description: "The smallest useful graph.",
    category: "getting_started",
    features: ["ai", "flow_control"],
    builtin: true,
  },
  {
    id: "builtin-fetch",
    name: "Fetch and Summarize",
    category: "basics",
    features: ["ai", "connect", "flow_control"],
    builtin: true,
  },
  {
    id: "org-1",
    name: "Our Approval Gate",
    category: "advanced",
    features: ["flow_control"],
  },
];

/**
 * Renders the route at its REAL nesting depth — `templates` and `canvas` as
 * sibling children under the `/workflows` mount — since #1349's whole outcome
 * is where Use Template lands you, and that depends on how a relative
 * navigation resolves.
 *
 * `federated` picks the router frame. Both are real: shell-mfe mounts the app
 * at a splat route with NO basename (the frame every user is in), while the
 * standalone bootstrap uses `basename="/workflows"`. They disagree about what
 * `useLocation().pathname` contains, so a navigation target that hardcodes
 * the prefix is correct in exactly one of them.
 */
function renderRoute({ federated = true }: { federated?: boolean } = {}) {
  const tree = (
    <Routes>
      <Route path="/workflows">
        <Route path="templates" element={<TemplatesRoute />} />
        <Route path="canvas" element={<div data-testid="canvas-landed" />} />
      </Route>
    </Routes>
  );
  render(
    federated ? (
      <MemoryRouter initialEntries={["/workflows/templates"]}>{tree}</MemoryRouter>
    ) : (
      // Under a basename the router sees "/templates"; declaring the same
      // "/workflows" parent keeps the ROUTE shape identical while the
      // PATHNAME differs, which is exactly the axis under test.
      <MemoryRouter basename="/workflows" initialEntries={["/workflows/templates"]}>
        <Routes>
          <Route path="templates" element={<TemplatesRoute />} />
          <Route path="canvas" element={<div data-testid="canvas-landed" />} />
        </Routes>
      </MemoryRouter>
    ),
  );
}

async function waitForLibrary(): Promise<void> {
  await waitFor(() =>
    expect(screen.getByRole("heading", { name: m.workflow_templates_title() })).toBeInTheDocument(),
  );
}

// ---------------------------------------------------------------------------
// #1346 — browse by category
// ---------------------------------------------------------------------------

test("renders the three sections in order: Getting Started, Basics, Advanced", async () => {
  mockLibrary(LIBRARY);
  renderRoute();
  await waitForLibrary();

  const headers = screen.getAllByRole("button", { expanded: true });
  const labels = headers.map((h) => h.textContent ?? "");
  expect(labels[0]).toContain(m.workflow_templates_category_getting_started());
  expect(labels[1]).toContain(m.workflow_templates_category_basics());
  expect(labels[2]).toContain(m.workflow_templates_category_advanced());
});

test("shows each template's name under its own section", async () => {
