test("Delete refetches the library rather than splicing the row out locally", async () => {
  const user = userEvent.setup();
  const listCalls = vi.fn();
  let remaining: readonly WireTemplate[] = LIBRARY;
  server.use(
    http.get("/api/v1/workflows/templates", () => {
      listCalls();
      return HttpResponse.json({
        data: {
          templates: remaining.map((t) => ({
            description: "",
            tags: [],
            features: [],
            unknown_node_types: [],
            builtin: false,
            created_at: "",
            ...t,
          })),
        },
      });
    }),
    http.delete("/api/v1/workflows/templates/org-1", () => {
      remaining = LIBRARY.filter((t) => t.id !== "org-1");
      return new HttpResponse(null, { status: 204 });
    }),
  );
  renderRoute();
  await waitForLibrary();

  const orgCard = screen.getByText("Our Approval Gate").closest("li") as HTMLElement;
  await user.click(
    within(orgCard).getByRole("button", {
