    }),
  );

  await waitFor(() => expect(screen.queryByText("Our Approval Gate")).not.toBeInTheDocument());
  // The merge of built-ins and org rows is the server's; re-reading it beats
  // reconstructing that ordering in the client.
  expect(listCalls).toHaveBeenCalledTimes(2);
});

