test("a second Use Template click while one is in flight does not mint a second workflow", async () => {
  // The button is disabled mid-flight, but the guard is what actually
  // prevents a double-mint — a disabled attribute is a UI hint, and two
  // stray workflows is the kind of mess a user has to clean up by hand.
  const user = userEvent.setup();
  mockLibrary(LIBRARY);
  let release = (): void => {};
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  const instantiations = vi.fn();
  server.use(
    http.post("/api/v1/workflows/templates/:id\\:instantiate", async () => {
      instantiations();
      await gate;
      return HttpResponse.json({ data: { workflow_id: "w-new" } });
    }),
  );
  renderRoute();
  await waitForLibrary();

  const card = screen.getByText("Your First Workflow").closest("li") as HTMLElement;
  const useButton = within(card).getByRole("button", { name: m.workflow_templates_use() });
  await user.click(useButton);

  await waitFor(() =>
    expect(
      within(card).getByRole("button", { name: m.workflow_templates_use_pending() }),
    ).toBeDisabled(),
  );

  // Drive the handler directly rather than through the disabled button, so
  // the assertion is about the guard and not about `disabled`.
  const otherCard = screen.getByText("Our Approval Gate").closest("li") as HTMLElement;
  await user.click(
    within(otherCard).getByRole("button", { name: m.workflow_templates_use() }),
  );

  expect(instantiations).toHaveBeenCalledTimes(1);
  release();
  await waitFor(() => expect(screen.getByTestId("canvas-landed")).toBeInTheDocument());
});

